import sys
import openpyxl
from openpyxl.utils import get_column_letter
from openpyxl.utils.cell import range_boundaries

SRC = '/root/data/workbook.xlsx'
DST = '/root/output/result.xlsx'


def cell_str(v):
    if v is None:
        return ''
    if isinstance(v, str):
        return v
    return str(v)


def is_year(v):
    if v is None:
        return False
    if isinstance(v, (int, float)):
        iv = int(v)
        return abs(v - iv) < 1e-9 and 1900 <= iv <= 2200
    if isinstance(v, str):
        s = v.strip()
        if s.isdigit():
            iv = int(s)
            return 1900 <= iv <= 2200
    return False


def dump_range(ws, cell_range, max_width=40):
    min_col, min_row, max_col, max_row = range_boundaries(cell_range)
    rows = []
    for r in range(min_row, max_row + 1):
        row = []
        for c in range(min_col, max_col + 1):
            v = ws.cell(row=r, column=c).value
            s = cell_str(v)
            if len(s) > max_width:
                s = s[: max_width - 3] + '...'
            row.append(s)
        rows.append(row)
    return rows


def pretty_print_rect(ws, top_left, bottom_right, start_row, end_row, start_col, end_col):
    # Prints a rectangle with column letters and row numbers.
    rect = dump_range(ws, f"{top_left}:{bottom_right}", max_width=60)
    header = [get_column_letter(c) for c in range(start_col, end_col + 1)]
    print('      ' + ' | '.join([h.rjust(4) for h in header]))

    def pad(x):
        x = x.replace('\n', ' ') if isinstance(x, str) else x
        return (x[:18] + '…') if len(x) > 19 else x

    for i, r in enumerate(range(start_row, end_row + 1)):
        rowvals = rect[i]
        pretty = ' | '.join([pad(v).rjust(4) for v in rowvals])
        print(f'R{r:02d}: ' + pretty)


def infer_data_layout(ws_data):
    # Find header row with years between rows 21-38.
    header_row = None
    header_year_cols = []
    for r in range(21, 39):
        year_cols = []
        for c in range(1, 51):
            v = ws_data.cell(row=r, column=c).value
            if is_year(v):
                year_cols.append(c)
        if len(year_cols) >= 3:
            header_row = r
            header_year_cols = year_cols
            break

    if header_row is None:
        raise RuntimeError('Could not infer year header row in Data!21:38')

    series_start = header_row + 1
    series_end = 38

    # Infer series code column by scoring non-empty string-ish column.
    col_scores = []
    for c in range(1, 51):
        nonempty = 0
        strcount = 0
        numcount = 0
        for r in range(series_start, series_end + 1):
            v = ws_data.cell(row=r, column=c).value
            if v is None or v == '':
                continue
            nonempty += 1
            if isinstance(v, str):
                strcount += 1
            elif isinstance(v, (int, float)):
                numcount += 1
        if nonempty == 0:
            continue
        score = (strcount - numcount) * 10 + nonempty
        col_scores.append((score, c, nonempty, strcount, numcount))

    col_scores.sort(reverse=True)
    if not col_scores:
        raise RuntimeError('Could not infer series code column in Data sheet')

    series_code_col = col_scores[0][1]

    min_year_col = min(header_year_cols)
    max_year_col = max(header_year_cols)

    # If inferred code col overlaps year span, assume years start right after code col.
    if min_year_col <= series_code_col <= max_year_col:
        if series_code_col == min_year_col:
            min_year_col += 1

    code_range = f"Data!${get_column_letter(series_code_col)}${series_start}:${get_column_letter(series_code_col)}${series_end}"
    year_range = f"Data!${get_column_letter(min_year_col)}${header_row}:${get_column_letter(max_year_col)}${header_row}"
    data_range = f"Data!${get_column_letter(min_year_col)}${series_start}:${get_column_letter(max_year_col)}${series_end}"

    return {
        'header_row': header_row,
        'min_year_col': min_year_col,
        'max_year_col': max_year_col,
        'series_start': series_start,
        'series_end': series_end,
        'series_code_col': series_code_col,
        'code_range': code_range,
        'year_range': year_range,
        'data_range': data_range,
    }


def row_label_text(ws_task, r):
    parts = []
    for col in ['A', 'B', 'C', 'D']:
        v = ws_task[f'{col}{r}'].value
        if v is None:
            continue
        parts.append(str(v))
    return ' '.join(parts).strip().lower()


def main():
    wb = openpyxl.load_workbook(DST, data_only=False)
    print('=== Phase 0: Setup and Inspection ===')
    print('Workbook:', DST)
    print('Sheet names:', wb.sheetnames)

    for s in ['Task', 'Data']:
        if s not in wb.sheetnames:
            raise SystemExit(f'Missing required sheet: {s}')

    ws_task = wb['Task']
    ws_data = wb['Data']

    print('\n-- Task sheet: Row 10 (H10:L10) year headers --')
    row10 = dump_range(ws_task, 'H10:L10')[0]
    print('H10..L10:', row10)

    print('\n-- Task sheet: Column D (rows 12-31) series codes --')
    for r in range(12, 32):
        print(f'D{r}:', cell_str(ws_task[f'D{r}'].value))

    print('\n-- Task sheet: Labels in columns A-C / D for rows 12-17, 19-24, 26-31, 35-40, 42-47, 50 --')
    rows_to_check = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)) + list(range(35, 41)) + list(range(42, 48)) + [50]
    for r in rows_to_check:
        a = cell_str(ws_task[f'A{r}'].value)
        b = cell_str(ws_task[f'B{r}'].value)
        c = cell_str(ws_task[f'C{r}'].value)
        d = cell_str(ws_task[f'D{r}'].value)
        if any([a, b, c, d]):
            print(f'Row {r:>2}: A={a!r}  B={b!r}  C={c!r}  D={d!r}')

    print('\n-- Task sheet: Rows 35-50 (structure, cols A-L) --')
    pretty_print_rect(ws_task, 'A35', 'L50', 35, 50, 1, 12)

    print('\n-- Task sheet: Existing values/formulas in H35:L50 --')
    for r in range(35, 51):
        vals = []
        for col in ['H', 'I', 'J', 'K', 'L']:
            vals.append(cell_str(ws_task[f'{col}{r}'].value))
        print(f'Row {r}:', vals)

    print('\n-- Data sheet: Rows 21-38 (cols A-N) --')
    pretty_print_rect(ws_data, 'A21', 'N38', 21, 38, 1, 14)

    layout = infer_data_layout(ws_data)

    print('\n=== Inferred Data layout (used for formulas) ===')
    print('Header row (years):', layout['header_row'])
    print('Year columns:', f"{get_column_letter(layout['min_year_col'])}..{get_column_letter(layout['max_year_col'])}")
    print('Series rows:', f"{layout['series_start']}..{layout['series_end']}")
    print('Series code column:', get_column_letter(layout['series_code_col']))
    print('INDEX data_range:', layout['data_range'])
    print('MATCH code_range:', layout['code_range'])
    print('MATCH year_range:', layout['year_range'])

    # Phase 1: write lookup formulas
    print('\n=== Phase 1: Populate lookup formulas ===')

    def write_lookup_block(r1, r2):
        for r in range(r1, r2 + 1):
            for col in ['H', 'I', 'J', 'K', 'L']:
                year_ref = f"{col}$10"
                code_ref = f"$D{r}"
                f = f"=INDEX({layout['data_range']}, MATCH({code_ref}, {layout['code_range']}, 0), MATCH({year_ref}, {layout['year_range']}, 0))"
                ws_task[f'{col}{r}'].value = f

    write_lookup_block(12, 17)
    write_lookup_block(19, 24)
    write_lookup_block(26, 31)

    # Phase 2: Net Production Slack
    print('\n=== Phase 2: Net Production Slack (H35:L40) ===')
    headers = {12: row_label_text(ws_task, 11), 19: row_label_text(ws_task, 18), 26: row_label_text(ws_task, 25)}
    print('Block header texts (rows 11/18/25):', headers)

    finished_start = None
    scrap_start = None
    capacity_start = None

    for start, txt in headers.items():
        if 'finished' in txt and 'output' in txt:
            finished_start = start
        if 'scrap' in txt or 'rework' in txt:
            scrap_start = start
        if ('rated' in txt and 'capacity' in txt) or ('production capacity' in txt):
            capacity_start = start

    if finished_start is None or scrap_start is None or capacity_start is None:
        print('WARNING: Could not uniquely identify all block types from header labels; defaulting to 12=Finished Output, 19=Scrap And Rework, 26=Rated Production Capacity')
        finished_start = finished_start or 12
        scrap_start = scrap_start or 19
        capacity_start = capacity_start or 26

    print('Using mapping:', {
        'Finished Output start row': finished_start,
        'Scrap And Rework start row': scrap_start,
        'Rated Production Capacity start row': capacity_start,
    })

    for i, r in enumerate(range(35, 41)):
        fin_r = finished_start + i
        scr_r = scrap_start + i
        cap_r = capacity_start + i
        for col in ['H', 'I', 'J', 'K', 'L']:
            ws_task[f'{col}{r}'].value = f"=({col}{fin_r}-{col}{scr_r})/{col}{cap_r}*100"

    # Phase 3: Summary stats (H42:L47)
    print('\n=== Phase 3: Summary Statistics (H42:L47) ===')

    def detect_stat(r):
        txt = ' '.join([cell_str(ws_task[f'{c}{r}'].value) for c in ['A', 'B', 'C']]).strip().lower()
        txt = txt.replace('%', '')
        if 'min' in txt:
            return 'MIN'
        if 'max' in txt:
            return 'MAX'
        if 'median' in txt:
            return 'MEDIAN'
        if 'average' in txt or 'mean' in txt:
            return 'AVERAGE'
        if 'percentile' in txt or 'quartile' in txt or 'q1' in txt or 'q3' in txt or '25' in txt or '75' in txt:
            if '25' in txt or 'q1' in txt:
                return 'P25'
            if '75' in txt or 'q3' in txt:
                return 'P75'
            return 'PERCENTILE'
        return None

    detected = {r: detect_stat(r) for r in range(42, 48)}
    print('Detected row stat labels:', detected)

    ordered = ['MIN', 'MAX', 'MEDIAN', 'AVERAGE', 'P25', 'P75']
    assign = {}
    used = set()

    for r in range(42, 48):
        s = detected[r]
        if s in ordered and s not in used:
            assign[r] = s
            used.add(s)

    remaining = [s for s in ordered if s not in used]
    for r in range(42, 48):
        if r not in assign:
            assign[r] = remaining.pop(0)

    print('Final row->stat assignment:', assign)

    for r in range(42, 48):
        stat = assign[r]
        for col in ['H', 'I', 'J', 'K', 'L']:
            rng = f"{col}35:{col}40"
            if stat == 'MIN':
                f = f"=MIN({rng})"
            elif stat == 'MAX':
                f = f"=MAX({rng})"
            elif stat == 'MEDIAN':
                f = f"=MEDIAN({rng})"
            elif stat == 'AVERAGE':
                f = f"=AVERAGE({rng})"
            elif stat == 'P25':
                f = f"=PERCENTILE({rng},0.25)"
            elif stat == 'P75':
                f = f"=PERCENTILE({rng},0.75)"
            else:
                f = f"=AVERAGE({rng})"
            ws_task[f'{col}{r}'].value = f

    # Phase 4: Weighted mean (H50:L50)
    print('\n=== Phase 4: Weighted Mean (H50:L50) ===')
    for col in ['H', 'I', 'J', 'K', 'L']:
        values_rng = f"{col}35:{col}40"
        weights_rng = f"{col}{capacity_start}:{col}{capacity_start + 5}"
        ws_task[f'{col}50'].value = f"=SUMPRODUCT({values_rng}, {weights_rng})/SUM({weights_rng})"

    # Save
    wb.save(DST)
    print('\nSaved to:', DST)

    # Validate by reopening
    wb2 = openpyxl.load_workbook(DST, data_only=False)
    print('\n=== Phase 5: Validation ===')
    print('Sheets after save:', wb2.sheetnames)

    ws2 = wb2['Task']

    def check_formula_range(rng):
        min_col, min_row, max_col, max_row = range_boundaries(rng)
        bad = []
        samples = []
        for r in range(min_row, max_row + 1):
            for c in range(min_col, max_col + 1):
                addr = f"{get_column_letter(c)}{r}"
                v = ws2[addr].value
                ok = isinstance(v, str) and v.startswith('=')
                if not ok:
                    bad.append((addr, v))
                if len(samples) < 3:
                    samples.append((addr, v))
        return bad, samples

    ranges = {
        'H12:L17': 'H12:L17',
        'H19:L24': 'H19:L24',
        'H26:L31': 'H26:L31',
        'H35:L40': 'H35:L40',
        'H42:L47': 'H42:L47',
        'H50:L50': 'H50:L50',
    }

    for label, rng in ranges.items():
        bad, samples = check_formula_range(rng)
        print(f'Range {label}: bad_cells={len(bad)}')
        if bad:
            print('  First few bad:', bad[:5])
        print('  Sample:')
        for addr, v in samples:
            print('   ', addr, '->', v)


if __name__ == '__main__':
    main()
